using System; using UnityEngine;
public sealed class PalettePanel:MonoBehaviour { public RectTransform Rect; public event Action<string> OnNodeTypePressed; public void Build(Transform p){var go=new GameObject("Palette",typeof(RectTransform));go.transform.SetParent(p,false);Rect=go.GetComponent<RectTransform>();Rect.anchorMin=Rect.anchorMax=new(0,1);Rect.pivot=new(0,1);Rect.sizeDelta=new(176,684);Rect.anchoredPosition=new(0,-44);var bg=go.AddComponent<PanelGraphic>();bg.Fill=Theme.Paper;var title=PixelText.Create(go.transform,"模块",Theme.Ink);title.rectTransform.anchoredPosition=new(10,-52);int i=0;foreach(var kv in NodeCatalog.All){var label=PixelText.Create(go.transform,kv.Title,Theme.Ink);label.rectTransform.anchoredPosition=new(28,-(76+i*24));var sw=new GameObject("Color",typeof(RectTransform));sw.transform.SetParent(go.transform,false);var sr=sw.GetComponent<RectTransform>();sr.anchoredPosition=new(10,-(76+i*24));sr.sizeDelta=new(12,12);sw.AddComponent<PanelGraphic>().Fill=Theme.Mint;i++;}}}
